@layer moduix.components {
  .root {
    --_input-height: var(--moduix-size-md);
    --_input-padding-x: var(--moduix-spacing-3);
    --_input-padding-y: var(--moduix-spacing-1);
    --_input-font-size: var(--moduix-text-md);
    --_input-line-height: var(--moduix-line-height-text-md);

    box-sizing: border-box;
    width: var(--moduix-input-width, 100%);
    min-width: 0;
    min-height: var(--moduix-input-height, var(--_input-height));
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-input-radius, var(--moduix-radius-md));
    padding: var(--_input-padding-y) var(--_input-padding-x);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    font: inherit;
    font-size: var(--_input-font-size);
    line-height: var(--_input-line-height);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &::placeholder {
      color: var(--moduix-color-muted-foreground);
    }

    &::file-selector-button {
      margin-inline-end: var(--moduix-spacing-3);
      border: var(--moduix-border-width-sm) solid var(--moduix-color-primary);
      border-radius: var(--moduix-radius-md);
      padding: var(--moduix-spacing-0-5) var(--moduix-spacing-2);
      background-color: var(--moduix-color-primary);
      color: var(--moduix-color-primary-foreground);
      font: inherit;
      font-weight: var(--moduix-weight-medium);
      line-height: inherit;
      cursor: pointer;
      transition: background-color var(--moduix-transition-default);

      @media (hover: hover) {
        &:hover {
          background-color: var(--moduix-color-foreground);
        }
      }
    }

    /* The native `size` attribute (`htmlSize`) sets a character-based width. */
    &[size] {
      width: var(--moduix-input-width, auto);
    }

    &:focus-visible {
      outline-color: var(--moduix-color-ring);
    }

    &:is([data-invalid], [aria-invalid='true']) {
      border-color: var(--moduix-color-destructive);

      &:focus-visible {
        outline-color: var(--moduix-color-destructive);
      }
    }

    &:is([data-disabled], :disabled) {
      pointer-events: none;
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled],
          [data-slot='input-group-root']:has(
            [data-slot='input-root']:is([data-disabled], :disabled)
          )
        )
        & {
        opacity: 1;
      }
    }

    &[data-size='xs'] {
      --_input-height: var(--moduix-size-xs);
      --_input-padding-x: var(--moduix-spacing-2);
      --_input-padding-y: var(--moduix-spacing-0-5);
      --_input-font-size: var(--moduix-text-xs);
      --_input-line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='sm'] {
      --_input-height: var(--moduix-size-sm);
      --_input-padding-x: var(--moduix-spacing-2);
      --_input-font-size: var(--moduix-text-sm);
      --_input-line-height: var(--moduix-line-height-text-sm);
    }

    &[data-size='lg'] {
      --_input-height: var(--moduix-size-lg);
      --_input-padding-x: var(--moduix-spacing-4);
      --_input-font-size: var(--moduix-text-lg);
      --_input-line-height: var(--moduix-line-height-text-lg);
    }

    &[data-size='xl'] {
      --_input-height: var(--moduix-size-xl);
      --_input-padding-x: var(--moduix-spacing-4);
      --_input-padding-y: var(--moduix-spacing-2);
      --_input-font-size: var(--moduix-text-lg);
      --_input-line-height: var(--moduix-line-height-text-lg);
    }
  }
}
